# Task 1: Type-safe sum
def sum_numbers(*args):
    if not all(isinstance(arg, (int, float)) for arg in args):
        raise TypeError('All arguments must be numbers')
    return sum(args)

# Task 2: Argument gatekeeper
def validate_and_process(multiplier, *args, min_args=1, max_args=5):
    if len(args) < min_args:
        raise ValueError('Not enough arguments')
    if len(args) > max_args:
        raise ValueError('Too many arguments')
    return [multiplier * arg for arg in args]

# Task 3: Dynamic server configuration
def configure_server(**kwargs):
    defaults = {'host': 'localhost', 'port': 8080, 'debug': False}
    config = defaults.copy()
    config.update(kwargs)
    return config

# Task 4: Keyword argument filtering
def filter_options(**kwargs):
    allowed_keys = {'color', 'size', 'weight'}
    return {k: v for k, v in kwargs.items() if k in allowed_keys}

# Task 5: Build a validated request
def build_request(endpoint, *args, **kwargs):
    if not all(isinstance(tag, str) for tag in args):
        raise TypeError('All tags must be strings')
    allowed_keys = {'method', 'timeout', 'retries'}
    defaults = {'method': 'GET', 'timeout': 30, 'retries': 3}
    options = defaults.copy()
    options.update({k: v for k, v in kwargs.items() if k in allowed_keys})
    return {'endpoint': endpoint, 'tags': args, 'options': options}

