if 'sum_numbers' not in globals():
    raise AssertionError('Task 1: sum_numbers not defined')
fn = globals()['sum_numbers']
if fn(1, 2, 3, 4) != 10:
    raise AssertionError('Task 1: sum_numbers(1,2,3,4) should return 10')
if fn(1.5, 2.5) != 4.0:
    raise AssertionError('Task 1: sum_numbers(1.5,2.5) should return 4.0')
if fn() != 0:
    raise AssertionError('Task 1: sum_numbers() should return 0')
try:
    fn(1, '2', 3)
    raise AssertionError('Task 1: Should raise TypeError for non-number')
except TypeError:
    pass
print('TEST_PASSED')

if 'validate_and_process' not in globals():
    raise AssertionError('Task 2: validate_and_process not defined')
fn = globals()['validate_and_process']
if fn(3, 1, 2, 3) != [3, 6, 9]:
    raise AssertionError('Task 2: validate_and_process(3,1,2,3) should return [3,6,9]')
try:
    fn(2, 10, min_args=2)
    raise AssertionError('Task 2: Should raise ValueError when too few args')
except ValueError:
    pass
try:
    fn(2, 1, 2, 3, 4, 5, 6, max_args=5)
    raise AssertionError('Task 2: Should raise ValueError when too many args')
except ValueError:
    pass
print('TEST_PASSED')

if 'configure_server' not in globals():
    raise AssertionError('Task 3: configure_server not defined')
fn = globals()['configure_server']
result = fn(port=9000, debug=True)
if result is None:
    raise AssertionError('Task 3: Function must return the config dictionary')
if result.get('host') != 'localhost':
    raise AssertionError('Task 3: host should default to localhost')
if result.get('port') != 9000:
    raise AssertionError('Task 3: port should be overridden to 9000')
if result.get('debug') != True:
    raise AssertionError('Task 3: debug should be overridden to True')
result2 = fn()
if result2 != {'host': 'localhost', 'port': 8080, 'debug': False}:
    raise AssertionError('Task 3: Empty call should return defaults')
result3 = fn(port=9000)
result4 = fn()
if result4.get('port') != 8080:
    raise AssertionError('Task 3: Use defaults.copy() to avoid mutation')
print('TEST_PASSED')

if 'filter_options' not in globals():
    raise AssertionError('Task 4: filter_options not defined')
fn = globals()['filter_options']
result = fn(color='red', size='large', price=100, brand='Nike')
if result is None:
    raise AssertionError('Task 4: Function must return the filtered dictionary')
if result.get('color') != 'red' or result.get('size') != 'large':
    raise AssertionError('Task 4: Should keep allowed keys')
if 'price' in result or 'brand' in result:
    raise AssertionError('Task 4: Should filter disallowed keys')
if fn(weight='10kg').get('weight') != '10kg':
    raise AssertionError('Task 4: Should allow weight key')
if fn(price=50) != {}:
    raise AssertionError('Task 4: No allowed keys should return empty dict')
print('TEST_PASSED')

if 'build_request' not in globals():
    raise AssertionError('Task 5: build_request not defined')
fn = globals()['build_request']
result = fn('/api/users', 'admin', 'active', method='POST', timeout=60)
if result is None:
    raise AssertionError('Task 5: Function must return the request dictionary')
if result['endpoint'] != '/api/users':
    raise AssertionError('Task 5: endpoint incorrect')
if result['tags'] != ('admin', 'active'):
    raise AssertionError('Task 5: tags incorrect')
if result['options']['method'] != 'POST':
    raise AssertionError('Task 5: method should be POST')
if result['options']['timeout'] != 60:
    raise AssertionError('Task 5: timeout should be 60')
if result['options']['retries'] != 3:
    raise AssertionError('Task 5: retries should default to 3')
result2 = fn('/api/health')
if result2['tags'] != ():
    raise AssertionError('Task 5: Empty tags should be empty tuple')
try:
    fn('/api/items', 'valid', 123)
    raise AssertionError('Task 5: Should raise TypeError for non-string tag')
except TypeError:
